\section{Experiments}
\label{sec:experiments}

\subsection{Experimental Setup}
\label{sec:setup}

\paragraph{Benchmark and model.}
We evaluate on the LIBERO-Goal suite~\cite{liu2023_libero}, comprising 10 tabletop manipulation tasks with 50 human demonstrations each.
We use OpenVLA-7B~\cite{kim2024_openvla,karamcheti2024}, a vision-language-action model consisting of a DinoSigLIP fused vision backbone~\cite{zhai2023_siglip,oquab2024_dinov2} (DINOv2 ViT-L/14 + SigLIP-SO400M), an MLP projector, and a Llama-2 7B language backbone, pretrained on the Open X-Embodiment dataset.

\paragraph{Representation sources.}
We extract representations from six sources:
(a)~\textbf{DinoSigLIP+Projector}---the vision encoder output after MLP projection (2{,}176-D $\to$ 4{,}096-D) into LLM input space;
(b)~\textbf{LLM image\_mean}---the mean of image token activations at each LLM layer;
(c)~\textbf{LLM last\_preaction}---the final token position before action decoding (readout token) at each LLM layer;
(d)~\textbf{DINOv2 ViT-L/14}~\cite{oquab2024_dinov2} (\texttt{cls\_token} and \texttt{patch\_mean});
(e)~\textbf{CLIP ViT-L/14}~\cite{radford2021_clip} (\texttt{patch\_mean}); and
(f)~\textbf{Branch-split}---the DINOv2 branch (1{,}088-D) and SigLIP branch (1{,}088-D) extracted separately before fusion, plus the fused 2{,}176-D representation before projection.
Sources (d) and (e) serve as external baselines with no VLA training signal.

\paragraph{Experimental conditions.}
We use a $2 \times 2$ factorial design crossing \emph{training status} (trained vs.\ untrained) with \emph{instruction presence} (with vs.\ without language instruction).
The untrained control applies \texttt{from\_config()} to reinitialize the LLM parameters (6.74B random weights) while preserving the frozen DinoSigLIP encoder, isolating the LLM's learned contribution from the vision encoder's pretrained geometry.

\paragraph{RSA.}
Following~\cite{kriegeskorte2008}, we compute within-task pairwise RDMs using Euclidean distance over full trajectories (50 demos/task), and report Spearman rank correlation $\rho$ between representation and action RDMs, averaged across the 10 tasks.
95\% confidence intervals are computed from 10{,}000 bootstrap resamples.

\paragraph{Functional probes.}
We train MLP probes (input $\to$ 256 $\to$ 7) with Adam (lr${}=10^{-3}$, batch size 256, 50 epochs, early stopping patience 5) to predict next-step 7-D action vectors from frozen representations~\cite{alain2017}. We report mean $R^2$ across action dimensions.

%------------------------------------------------------------------
\subsection{Vision Encoder Dominance}
\label{sec:vision_dominance}

Table~\ref{tab:rsa_overview} reports RSA $\rho$ between each representation source and the action space.
Self-supervised DINOv2 provides the strongest action-relevant geometry: \texttt{cls\_token} achieves $\rho = 0.692$, the highest of any representation source, with \texttt{patch\_mean} at $\rho = 0.631$.
Both substantially exceed vision-language contrastive CLIP ($\rho = 0.557$), indicating that self-supervised pretraining yields stronger geometric alignment with the action space than vision-language alignment.
Functional probes corroborate this ordering: DINOv2 ($R^2 = 0.634$) $\approx$ Projector ($R^2 = 0.630$, $p = 0.557$, n.s.) $>$ CLIP ($R^2 = 0.587$, $p < 0.001$; Table~\ref{tab:probes}).

\paragraph{Branch-split analysis.}
To disentangle the contributions of the two encoder streams within DinoSigLIP, we extract representations from each branch separately.
The DINOv2 branch ($\rho = 0.619$) and SigLIP branch ($\rho = 0.621$) contribute nearly equally, with neither stream dominating.
Fusing the two branches yields $\rho = 0.634$, exceeding either individual branch---indicating that the fusion operation provides complementary geometric structure.
The MLP projector compresses this from 2{,}176-D to 4{,}096-D while reducing RSA from $0.634$ to $0.615$, suggesting that projection into LLM space incurs a modest geometric cost.

\paragraph{Metric sensitivity.}
The choice of similarity metric affects conclusions.
Linear CKA~\cite{kornblith2019} produces a different ranking from RSA: untrained LLM ($\text{CKA} = 0.089$) $>$ trained LLM ($0.083$) $>$ DinoSigLIP+Projector ($0.081$) $>$ DINOv2 ($0.066$), partially reversing the RSA ordering (Figure~\ref{fig:metric_comparison}).
RDM kernel CKA yields Trained ($0.260$) $\approx$ Proj ($0.257$) $>$ Untrained ($0.246$) $>$ DINOv2 ($0.241$), with the Trained--Projector gap negligible ($\Delta = 0.003$).
This RSA--CKA divergence reflects the different geometric properties captured by each metric and underscores the importance of multi-metric evaluation.

\begin{table}[t]
\centering
\caption{RSA between representation and action RDMs ($\rho$ $\uparrow$, Method B: within-task pairing, Euclidean distance, 50 demos/task). Self-supervised DINOv2 achieves the highest geometric alignment. Branch-split shows both streams contribute equally; fusion provides complementary structure. 95\% CIs from 10{,}000 bootstrap resamples.}
\label{tab:rsa_overview}
\small
\begin{tabular}{llcc}
\toprule
Source & Aggregation & RSA $\rho$ & 95\% CI \\
\midrule
DINOv2 ViT-L/14 & cls\_token & \textbf{0.692} & --- \\
Fused DinoSigLIP (2176-D) & --- & 0.634 & --- \\
DINOv2 ViT-L/14 & patch\_mean & 0.631 & --- \\
SigLIP branch (1088-D) & --- & 0.621 & --- \\
DINOv2 branch (1088-D) & --- & 0.619 & --- \\
DinoSigLIP+Projector & --- & 0.615 & {[0.526, 0.695]} \\
CLIP ViT-L/14 & patch\_mean & 0.557 & {[0.442, 0.660]} \\
\midrule
VLA Trained & image\_mean (L12 peak) & 0.628 & --- \\
VLA Trained & last\_preaction (L12) & 0.643 & --- \\
VLA Untrained & image\_mean (L0 peak) & 0.612 & --- \\
VLA Untrained & last\_preaction (L1 peak) & 0.626 & --- \\
\bottomrule
\end{tabular}
\end{table}

\begin{figure}[t]
\centering
\includegraphics[width=\columnwidth]{figures/fig2.pdf}
\caption{RSA with the action space ($\rho$) across representation sources. Self-supervised DINOv2 \texttt{cls\_token} ($\rho{=}0.692$) achieves the highest geometric alignment. Both encoder branches contribute equally within DinoSigLIP; fusion provides complementary structure ($0.634$); projection incurs modest geometric cost ($0.615$). CLIP ($0.557$) yields the weakest geometry among pretrained encoders. Error bars: 95\% bootstrap CIs.}
\label{fig:rsa_bar}
\end{figure}

%------------------------------------------------------------------
\subsection{Non-Monotonic LLM Transformation}
\label{sec:llm_transformation}

This experiment characterizes how the LLM transforms action-relevant structure inherited from the vision encoder across its 32 layers.
Figure~\ref{fig:layer_curves} reveals a non-monotonic pattern that challenges the assumption of simple degradation.

\paragraph{Inverted-U trajectory.}
For the trained model, image\_mean RSA follows an inverted-U: $\rho$ begins at $0.612$ (L0), \emph{rises} to a peak of $0.628$ at L12---exceeding the projector input ($0.615$)---then declines sharply to $0.422$ at L32 (Figure~\ref{fig:layer_curves}).
The first 12 layers \emph{enhance} geometric alignment with the action space beyond what the vision encoder provides; the subsequent 20 layers degrade it below the initial level.
This finding revises the prevailing view that LLMs uniformly degrade vision encoder representations~\cite{fang2025}: the LLM's middle layers produce the most action-aligned distributed representations in the entire pipeline.

\paragraph{Training shapes the trajectory.}
The non-monotonic pattern is training-dependent.
The untrained model peaks at L0 ($\rho = 0.612$) and decays monotonically through the remaining layers ($\rho = 0.545$ at L32), never exceeding the projector input.
Training thus creates the inverted-U by shifting the RSA peak from L0 to L12 while sharpening the late-layer decline.

\paragraph{RSA--CKA dissociation.}
CKA provides a contrasting perspective: trained image\_mean linear CKA rises monotonically from $0.081$ (L0) to $0.098$ (L32), showing no inverted-U.
This metric-level dissociation---RSA peaks at L12 while CKA increases through L32---reflects the different geometric properties captured by each metric: RSA measures local rank-order alignment with actions, while CKA captures global second-order structure.

\paragraph{Readout concentration.}
At the readout token (\texttt{last\_preaction}), the trained model concentrates action-relevant structure: readout RSA peaks at L12 ($\rho = 0.643$), exceeding both the projector ($0.615$) and the distributed image\_mean at the same layer ($0.628$).
Functional probes confirm this concentration: trained readout achieves $R^2 = 0.671$, exceeding DinoSigLIP+Projector ($R^2 = 0.630$, $\Delta = 0.041$; Table~\ref{tab:probes}, Figure~\ref{fig:probe_bars}).

\paragraph{Distributed degradation in late layers.}
While middle layers enhance action alignment, the overall LLM trajectory results in net degradation: image\_mean drops from $0.612$ (L0) to $0.422$ (L32), and probe $R^2$ decreases from $0.630$ (projector) to $0.599$ (L19 image\_mean, $\Delta = 0.031$, $p < 0.001$).
The LLM is thus neither a simple degrader nor a simple enhancer, but a non-monotonic transformer that first sharpens and then disperses action-relevant geometry.

\begin{table}[t]
\centering
\caption{Functional probe $R^2$ ($\uparrow$) for action prediction from frozen representations. The LLM degrades distributed representations (image\_mean) relative to the projector but concentrates superior action information at the readout token. DINOv2 is statistically indistinguishable from the projector.}
\label{tab:probes}
\small
\begin{tabular}{lcc}
\toprule
Representation & $R^2$ & $p$ vs.\ Proj. \\
\midrule
DinoSigLIP+Projector & 0.630 & --- \\
VLA Trained image\_mean (L19) & 0.599 & $<$0.001 \\
VLA Trained readout (L19) & \textbf{0.671} & $<$0.001 \\
\midrule
DINOv2 cls\_token & 0.634 & 0.557 (n.s.) \\
CLIP ViT-L/14 cls & 0.587 & $<$0.001 \\
\bottomrule
\end{tabular}
\end{table}

\begin{figure}[t]
\centering
\includegraphics[width=\columnwidth]{figures/fig3.pdf}
\caption{Per-layer RSA ($\rho$) with the action space. The trained model (solid lines) exhibits an inverted-U trajectory: RSA rises from L0 ($0.612$) to a peak at L12 ($0.628$, exceeding the projector input at $0.615$), then declines to L32 ($0.422$). The untrained model (dashed) peaks at L0 and decays monotonically. Training shifts the peak from L0 to L12 without creating higher peak values (best-vs-best $\Delta{=}0.017$, n.s.). Horizontal lines: DINOv2 cls ($\rho{=}0.692$) and projector ($\rho{=}0.615$) reference levels.}
\label{fig:layer_curves}
\end{figure}

\begin{figure}[t]
\centering
\includegraphics[width=\columnwidth]{figures/fig4.pdf}
\caption{Functional probe $R^2$ for action prediction. The LLM degrades distributed image\_mean ($R^2{=}0.599$) below the projector baseline ($0.630$) but concentrates superior information at the trained readout ($0.671$). DINOv2 ($0.634$) is statistically indistinguishable from the projector ($p{=}0.557$). Rankings are consistent with RSA: DINOv2 $\geq$ Projector $>$ CLIP ($0.587$).}
\label{fig:probe_bars}
\end{figure}

%------------------------------------------------------------------
\subsection{Training Redistributes, Does Not Create, Action Structure}
\label{sec:training_routing}

This experiment tests whether LLM training creates new action-relevant geometric structure or redistributes pre-existing structure by shifting when and where action alignment peaks.
Table~\ref{tab:training_effects} reports the effect of training across metrics.

\paragraph{Peak shift, not peak creation.}
Training shifts the image\_mean RSA peak from L0 ($\rho = 0.612$, untrained) to L12 ($\rho = 0.628$, trained), but does not produce a higher peak than the untrained model achieves at its own optimal layer.
Comparing each model at its respective peak (best-vs-best): $\Delta = +0.017$, 95\% CI includes zero, not significant.
However, at the same layer (L12): trained $\rho = 0.628$ vs.\ untrained $\rho = 0.550$, $\Delta = +0.079$, $p < 0.0001$---training has a large effect on \emph{where} action structure concentrates, but not on \emph{how much} total structure is available.

\paragraph{Instruction invariance.}
Language instructions do not modulate geometric structure.
Across four instruction conditions---normal, random, shuffled, and empty---all RSA values fall within $|\Delta| < 0.006$ of each other (Figure~\ref{fig:factorial}b), confirming content invariance.

\paragraph{Functional concentration requires training.}
In contrast to the geometric redistribution, readout probe $R^2$ shows a large training effect: $\Delta = +0.045$ ($p < 0.0001$).\footnote{The training effect comparison uses internally consistent p0 probes (trained readout $R^2 = 0.731$, untrained $0.686$) to ensure valid within-condition comparison; absolute values differ from the cross-representation comparison in Table~\ref{tab:probes}, which uses unified hyperparameters.}
Training concentrates action-relevant information at the readout position for decoding.

These results support a \emph{redistribution} interpretation: training teaches the LLM \emph{where} to concentrate action-relevant geometry (shifting the peak from L0 to L12), rather than creating new action-relevant representations.
The routing policy is learned; the representations themselves are inherited from the frozen vision encoder.

\begin{table}[t]
\centering
\caption{Training effects on action-relevant structure. Best-vs-best RSA comparison is not significant ($\Delta{=}0.017$), but same-layer comparison at L12 shows a large effect ($\Delta{=}0.079$, $p{<}0.0001$): training redistributes rather than creates geometric structure. Functional concentration at the readout requires training ($\Delta R^2{=}0.045$).}
\label{tab:training_effects}
\small
\begin{tabular}{lccc}
\toprule
Comparison & $\Delta$ & 95\% CI & $p$ \\
\midrule
Best-vs-best image\_mean RSA & $+$0.017 & incl.\ 0 & n.s. \\
Same-layer L12 image\_mean RSA & $+$0.079 & --- & $<$0.0001 \\
Training (readout $R^2$) & $+$0.045 & [$+$0.032, $+$0.058] & $<$0.0001 \\
Proj.\ vs.\ image\_mean ($R^2$) & $+$0.031 & --- & $<$0.001 \\
\bottomrule
\end{tabular}
\end{table}

\begin{figure}[t]
\centering
\includegraphics[width=\columnwidth]{figures/fig5.pdf}
\caption{\textbf{(a)}~Training $\times$ Instruction effects on image\_mean RSA. Training shifts the RSA peak from L0 to L12 without altering the peak magnitude (best-vs-best $\Delta{=}0.017$, n.s.). \textbf{(b)}~Instruction content control: all four conditions (normal, random, shuffled, empty) yield RSA within $|\Delta| < 0.006$, confirming instruction invariance.}
\label{fig:factorial}
\end{figure}

\begin{figure}[t]
\centering
\includegraphics[width=\columnwidth]{figures/fig6.pdf}
\caption{Comparison of three similarity metrics across representation sources. \textbf{(a)}~RSA (Spearman $\rho$): DINOv2 $>$ Proj $>$ Trained. \textbf{(b)}~Linear CKA~\cite{kornblith2019} partially reverses the ordering (Untrained $>$ Trained $>$ Proj $>$ DINOv2). \textbf{(c)}~RDM kernel CKA: Trained $\approx$ Proj ($\Delta{=}0.003$) $>$ Untrained $>$ DINOv2. The RSA--CKA dissociation illustrates that metric choice affects conclusions about representation structure.}
\label{fig:metric_comparison}
\end{figure}

